  }
  greet() {
    return 'Hi, ' + this.name;
  }
}

const u = new User('Ada');
console.log(u.greet()); // Hi, Ada
console.log(typeof User); // function — a class is a function
console.log(u.greet === new User('x').greet); // true — shared method

class Account {
  #balance = 0;
  constructor(start) { this.#balance = start; }
  deposit(n) { this.#balance += n; }
  get balance() { return this.#balance; }
}

class Savings extends Account {
  constructor(start, rate) {
    super(start);
    this.rate = rate;
  }
  addInterest() { this.deposit(this.balance * this.rate); }
}

const s = new Savings(100, 0.1);
s.addInterest();
console.log(s.balance);          // 110
console.log(s instanceof Account); // true
console.log(s.balance);          // 110, #balance is private

