class Stack {
  #items = [];
  push(item) { this.#items.push(item); }
  pop() { return this.#items.pop(); }
  get size() { return this.#items.length; }
}

const s = new Stack();
s.push(1);
s.push(2);
console.log(s.size);
console.log(s.pop());
console.log(s.size);

