solution.code:
class Animal {
  constructor(name) { this.name = name; }
}
class Dog extends Animal {
  constructor(name, breed) {
    super(name);      // initialize parent first
    this.breed = breed;
  }
}
const d = new Dog('Rex', 'Lab');
console.log(d.name, d.breed); // Rex Lab

class Shape {
  area() { return 0; }
  static largest(shapes) {
    return shapes.reduce((a, b) => (a.area() >= b.area() ? a : b));
  }
}

class Circle extends Shape {
  constructor(r) { super(); this.r = r; }
  area() { return Math.PI * this.r ** 2; }
}

class Rectangle extends Shape {
  constructor(w, h) { super(); this.w = w; this.h = h; }
  area() { return this.w * this.h; }
}

const shapes = [new Circle(2), new Rectangle(3, 5)];
console.log(Shape.largest(shapes).area()); // 15
